// computer keyboard -> notes; the canvas draws the piano and lights held keys
const KEYS = [
  ["a", "C4"], ["w", "C#4"], ["s", "D4"], ["e", "D#4"], ["d", "E4"],
  ["f", "F4"], ["t", "F#4"], ["g", "G4"], ["y", "G#4"], ["h", "A4"],
  ["u", "A#4"], ["j", "B4"], ["k", "C5"],
];
const NOTE = Object.fromEntries(KEYS);
const active = new Set();

// re-eval guard so edits don't stack listeners (same trick as the NES demo).
// It runs before this eval's own inputs are checked, so it must tolerate a
// previous run that never got a synth (the import resolves a beat later).
if (globalThis.__synthCleanup) globalThis.__synthCleanup();
if (!synth || !tone) return "waiting for tone.js…";
const down = (e) => {
  const n = NOTE[e.key];
  if (!n || e.repeat || e.metaKey || e.ctrlKey) return;
  if (tone.getContext().state !== "running") tone.start();
  synth.triggerAttack(n);
  active.add(n);
};
const up = (e) => {
  const n = NOTE[e.key];
  if (!n) return;
  synth.triggerRelease(n);
  active.delete(n);
};
window.addEventListener("keydown", down);
window.addEventListener("keyup", up);
globalThis.__synthCleanup = () => {
  window.removeEventListener("keydown", down);
  window.removeEventListener("keyup", up);
  synth?.releaseAll?.();
};

const draw = (ctx, { width: w, height: h }) => {
  ctx.fillStyle = "#242331";
  ctx.fillRect(0, 0, w, h);
  ctx.font = "10px monospace";
  const whites = KEYS.filter(([, n]) => !n.includes("#"));
  const ww = w / whites.length;
  const xs = {};
  whites.forEach(([, n], i) => (xs[n] = i * ww));
  for (const [k, n] of whites) {
    ctx.fillStyle = active.has(n) ? "#d9a13f" : "#d9d7eb";
    ctx.fillRect(xs[n] + 1, 6, ww - 2, h - 12);
    ctx.fillStyle = "#242331";
    ctx.fillText(k, xs[n] + ww / 2 - 3, h - 14);
  }
  for (const [k, n] of KEYS) {
    if (!n.includes("#")) continue;
    const x = xs[n.replace("#", "")] + ww * 0.65;
    ctx.fillStyle = active.has(n) ? "#d9a13f" : "#141320";
    ctx.fillRect(x, 6, ww * 0.7, (h - 12) * 0.58);
    ctx.fillStyle = "#d9d7eb";
    ctx.fillText(k, x + ww * 0.35 - 3, (h - 12) * 0.45);
  }
};
draw;
